#include "boot_ram.h"
#include <stdio.h>
#include <string.h>
static tf_model memory;
static br_model m;
static uint8_t boot[12288];
static unsigned checks,failed,groups,rom_calls,frees,commands,callbacks;
static uint32_t last_cb,last_arg,last_uart_length,clock_seen;
static int callback_cleared;
#define CHECK(x) do{++checks;if(!(x)){++failed;printf("FAIL %d %s\n",__LINE__,#x);}}while(0)
static void put(uint32_t a,uint32_t v,unsigned n){unsigned i;for(i=0;i<n;i++){memory.ram[a-TF_RAM_BASE+i]=(uint8_t)(v>>(8*i));memory.known[a-TF_RAM_BASE+i]=255;}}
static uint32_t get(uint32_t a,unsigned n){uint32_t v=0;unsigned i;for(i=0;i<n;i++)v|=(uint32_t)memory.ram[a-TF_RAM_BASE+i]<<(8*i);return v;}
static int rom(void *p,unsigned off,uint8_t task,uint16_t events,uint32_t ticks){(void)p;(void)ticks;CHECK(task==(off==92?4:3));if(off==92)CHECK(events==2);++rom_calls;return off==88?1:0;}
static br_flow release(void *p,uint32_t a){(void)p;CHECK(a==123||a==7);++frees;return BR_RETURNED;}
static br_flow callback(void *p,br_model *q,uint32_t cb,uint32_t arg){(void)p;CHECK(q==&m);last_cb=cb;last_arg=arg;++callbacks;callback_cleared=get(BR_REGISTRY+4,4)==0;return BR_RETURNED;}
static br_flow uart(void *p,br_model *q,uint8_t cmd,uint32_t address,uint16_t n){(void)p;CHECK(q==&m);CHECK(cmd=='S');CHECK(address==BR_UART);++commands;last_uart_length=n;clock_seen=get(0x20004090,4);CHECK(get(BR_UART+1033,1)==6);put(BR_UART,0xa5,1);return BR_RETURNED;}
static void fresh(void){br_backend b={NULL,rom,release,callback,uart};memset(&memory,0,sizeof(memory));br_init(&m,&memory,&b);CHECK(br_cold_start(&m,boot,sizeof(boot))==BR_RETURNED);put(0x2000408a,3,1);put(0x2000408d,4,1);rom_calls=frees=commands=callbacks=0;}
static size_t frame(uint8_t *p,uint8_t command,const uint8_t *data,size_t n){uint8_t s=(uint8_t)(command+(n>>8)+(n&255));size_t i;p[0]=0x55;p[1]=0x7f;p[2]=command;p[3]=(uint8_t)(n>>8);p[4]=(uint8_t)n;for(i=0;i<n;i++){p[5+i]=data[i];s=(uint8_t)(s+data[i]);}p[n+5]=s;return n+6;}
static void group(const char *s){++groups;printf("GROUP %s\n",s);}
static void startup(void){unsigned i;group("BOOT native data104 and BSS preserve external ROM and unrelated SRAM");memset(&memory,0,sizeof(memory));put(0x20000040,0x12345678,4);put(0x200099a0,0xab,1);br_init(&m,&memory,NULL);CHECK(br_cold_start(&m,boot,sizeof(boot))==BR_RETURNED);for(i=0;i<104;i++){CHECK(memory.ram[0x4000+i]==boot[0x2e90+i]);CHECK(memory.known[0x4000+i]==255);}CHECK(get(0x20000040,4)==0x12345678);CHECK(get(0x200099a0,1)==0xab);CHECK(memory.known[0x4068]==255);CHECK(memory.known[0x999f]==255);CHECK(memory.known[0x9a00]==0);}
static void registry(void){group("BOOT94CC single/repeat/duplicates share slots and clear before delivery");fresh();CHECK(br_schedule(&m,0x192c,0,200,123)==0);CHECK(m.last_ticks==320);CHECK(get(BR_REGISTRY+4,4)==0x192c);CHECK(br_schedule(&m,0x192c,0,400,456)==0);CHECK(frees==1);CHECK(get(BR_REGISTRY+8,4)==456);CHECK(br_schedule(&m,0x192c,1,0,7)==0);CHECK(get(BR_REGISTRY+16,4)==0x192c);CHECK(get(BR_REGISTRY+12,1)==0);CHECK(br_dispatch(&m,3)==2);CHECK(callbacks==1);CHECK(callback_cleared==1);CHECK(last_cb==0x192c);CHECK(last_arg==456);CHECK(get(BR_REGISTRY+16,4)==0x192c);CHECK(br_stop_startup(&m)==0);CHECK(get(BR_REGISTRY+16,4)==0x192c);CHECK(frees==1);CHECK(br_dispatch(&m,0x8000)==0);CHECK(get(0x2000be0c,4)==0);}
static void uart_state(void){uint8_t p[64],d[3]={1,2,3};size_t n;group("UART native struct, callback-before-state0, stale payload and timeout clear1036");fresh();put(BR_UART+1032,2,1);put(BR_UART+1034,44,1);n=frame(p,'S',d,3);CHECK(br_uart_receive(&m,p,n,100)==n);CHECK(commands==1);CHECK(last_uart_length==3);CHECK(clock_seen==100);CHECK(get(BR_UART,1)==0xa5);CHECK(get(BR_UART+1033,1)==0);CHECK(get(BR_UART+1032,1)==2);CHECK(get(BR_UART+1034,1)==44);n=frame(p,'S',NULL,0);CHECK(br_uart_receive(&m,p,n,101)==n);CHECK(commands==2);CHECK(get(BR_UART,1)==0xa5);put(0x20004090,100,4);CHECK(br_uart_receive(&m,NULL,0,4000)==0);CHECK(get(BR_UART+1032,1)==2);CHECK(get(0x20004090,4)==100);p[0]=0;CHECK(br_uart_receive(&m,p,1,3100)==1);CHECK(get(BR_UART+1032,1)==0);CHECK(get(BR_UART+1034,1)==0);CHECK(get(BR_UART,1)==0);CHECK(get(0x20004090,4)==3100);}
static void bounds(void){uint8_t b=7;group("known invalid parser/index resets; absent command adapter stops at callback");fresh();put(BR_UART+1033,7,1);CHECK(br_uart_receive(&m,&b,1,1)==1);CHECK(get(BR_UART+1033,1)==0);put(BR_UART+1033,5,1);put(BR_UART+1028,1026,2);put(BR_UART+1031,9,1);CHECK(br_uart_receive(&m,&b,1,2)==1);CHECK(get(BR_UART+1033,1)==0);CHECK(get(BR_UART+1031,1)==9);fresh();m.backend.uart_command=NULL;put(BR_UART+1033,6,1);put(BR_UART+1030,'S',1);put(BR_UART+1031,7,1);CHECK(br_uart_receive(&m,&b,1,2)==0);CHECK(m.flow==BR_HALT);CHECK(get(BR_UART+1033,1)==6);}
int main(int argc,char **argv){FILE *f;if(argc!=2)return 2;f=fopen(argv[1],"rb");if(!f||fread(boot,1,sizeof(boot),f)!=sizeof(boot)){if(f)fclose(f);return 2;}fclose(f);startup();registry();uart_state();bounds();printf("BOOT_RAM_RESULT groups=%u checks=%u failures=%u original_executed=no hardware=no\n",groups,checks,failed);return failed?1:0;}
